typedef enum an_ifc_validation_trace_kind { ifc_vtk_field,ifc_vtk_partition } an_ifc_validation_trace_kind;
typedef struct field_info_trace_data { a_const_char *name;size_t offset; } field_info_trace_data;
struct an_ifc_validation_trace {
  an_ifc_validation_trace_kind trace_kind;
  const an_ifc_validation_trace *parent;
#ifdef UNION_AS_STRUCT
#undef union
#endif
  union { field_info_trace_data field_info;an_ifc_partition_kind_index partition_info; };
#ifdef UNION_AS_STRUCT
#define union struct
#endif
};
static inline an_ifc_validation_trace an_ifc_validation_trace_field(a_const_char *name,size_t offset,const an_ifc_validation_trace *parent)
{ an_ifc_validation_trace result={0};result.trace_kind=ifc_vtk_field;result.parent=parent;result.field_info=(field_info_trace_data){name,offset};return result; }
static inline an_ifc_validation_trace an_ifc_validation_trace_partition(an_ifc_module_file *file,an_ifc_partition_kind kind,an_ifc_index_type index,const an_ifc_validation_trace *parent)
{ an_ifc_validation_trace result={0};result.trace_kind=ifc_vtk_partition;result.parent=parent;result.partition_info=(an_ifc_partition_kind_index){file,kind,index};return result; }
